# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: render
def render(xs, offset=4):
    return [v + offset for v in xs]

# region: fold
def fold(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: gather
def gather(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(digest(fold(render(shape(raw)))))

